"""Rebuild the documented #348 controls for the one trainable, unreplicated pair."""
from collections import Counter
from copy import deepcopy
import json
from pathlib import Path
import random
import sys

import numpy as np

sys.path.insert(0, str(Path.cwd()))
from vs import corpus, generators, ivtff


def eligible_page(page):
    lines = [ivtff.Line(line.id, line.page, line.n, line.unit, line.subtype,
                        [word for word in line.words if not ivtff.uncertain(word)],
                        line.para_start, line.para_end)
             for line in page.lines if line.unit == 'P']
    return ivtff.Page(page.id, page.order, dict(page.meta), lines)


def plant_words(pages, seed):
    planted = deepcopy(pages)
    existing = {word for page in planted for line in page.lines for word in line.words}
    lengths = {len(word) for word in existing if len(word) >= 4}
    markers = {}
    for hand, marker_stem in (('2', 'x'), ('5', 'g')):
        for length in lengths:
            candidates = (marker_stem + a + b + b * (length - 4) + c
                          for a in 'aoeyidkl' for b in 'ldknr' for c in 'aoey')
            markers[hand, length] = []
            for word in candidates:
                if word not in existing:
                    markers[hand, length].append(word)
                    existing.add(word)
                    if len(markers[hand, length]) == 4:
                        break
    summary = {}
    for page in planted:
        rng = random.Random(seed + 997 * page.order)
        positions = [(line, index) for line in page.lines for index, word in enumerate(line.words) if len(word) >= 4]
        selected = rng.sample(positions, round(0.10 * len(positions)))
        for line, index in selected:
            line.words[index] = rng.choice(markers[str(page.hand), len(line.words[index])])
        summary[page.id] = [len(selected), len(positions)]
    return planted, summary


def unit_rows(matrix):
    norms = np.linalg.norm(matrix, axis=1, keepdims=True)
    return matrix / np.maximum(norms, 1e-12)


def documents(train, test):
    words = [Counter(page.words({'P'})) for page in train + test]
    document_frequency = Counter(word for page in words[:len(train)] for word in page)
    vocab = {word: index for index, word in enumerate(sorted(word for word, count in document_frequency.items() if count >= 3))}
    matrix = np.zeros((len(words), len(vocab)))
    for i, counts in enumerate(words):
        for word, count in counts.items():
            if word in vocab:
                idf = 1 + np.log((1 + len(train)) / (1 + document_frequency[word]))
                matrix[i, vocab[word]] = count * idf
    matrix = unit_rows(matrix)
    return matrix[:len(train)], matrix[len(train):]


def pair_margin(train, test, seed):
    train_matrix, test_matrix = documents(train, test)
    rank = 5
    rng = np.random.default_rng(seed)
    train_weights = rng.uniform(0.1, 1.0, size=(len(train), rank))
    basis = rng.uniform(0.1, 1.0, size=(rank, train_matrix.shape[1]))
    eps = 1e-12
    for _ in range(300):
        train_weights *= (train_matrix @ basis.T) / (train_weights @ (basis @ basis.T) + eps)
        basis *= (train_weights.T @ train_matrix) / ((train_weights.T @ train_weights) @ basis + eps)
    scales = np.maximum(np.linalg.norm(basis, axis=1), eps)
    basis /= scales[:, None]
    train_weights *= scales
    test_weights = rng.uniform(0.1, 1.0, size=(len(test), rank))
    for _ in range(200):
        test_weights *= (test_matrix @ basis.T) / (test_weights @ (basis @ basis.T) + eps)
    train_weights = unit_rows(train_weights)
    test_weights = unit_rows(test_weights)
    centroids = unit_rows(np.array([train_weights[[str(p.hand) == hand for p in train]].mean(axis=0) for hand in ('2', '5')]))
    similarities = test_weights @ centroids.T
    return float(similarities[0, 0] + similarities[1, 1] - similarities[0, 1] - similarities[1, 0])


def main():
    metadata = json.loads(Path(sys.argv[1]).read_text())
    pair = next(p for p in metadata['matches']['local']['2-5']['pair_details'] if min(p['training_folios'].values()) >= 2)
    holdout_quires = set(pair['quires'])
    train_ids = {p['id'] for p in metadata['public_practice_training'] if p['quire'] not in holdout_quires and p['hand'] in ('2', '5')}
    results = {}
    for edition in ('zl', 'it'):
        train_pages, test_pages = corpus.split_pages('practice', edition)
        train_layout = [eligible_page(page) for page in train_pages if page.id in train_ids]
        test_index = {page.id: page for page in test_pages}
        test_layout = [eligible_page(test_index[pid]) for pid in pair['pages']]
        edition_results = {}
        for background in range(401, 407):
            copy = generators.g_self_citation(train_layout, train_layout + test_layout, seed=background)
            planted, plant_counts = plant_words(copy, background)
            output = {}
            n = len(train_layout)
            for case, pages in [('copy', copy), ('planted', planted)]:
                margins = [pair_margin(pages[:n], pages[n:], seed) for seed in (47, 83, 113)]
                output[case] = [round(x, 8) for x in margins]
            output['planted_test_word_counts'] = {p.id: plant_counts[p.id] for p in test_layout}
            edition_results[str(background)] = output
        results[edition] = edition_results
    print(json.dumps({'contrast':pair, 'training_pages':sorted(train_ids), 'controls':results}, indent=2))


if __name__ == '__main__':
    main()
